#!/usr/bin/env python3
"""Focused semantic harness for CVE-2025-22870 (x/net/http/httpproxy IPv6 zone).

This container has no Go toolchain, so the Go package cannot be compiled or run.
This harness does two things against the ACTUAL target source file found in the
current working directory (a clean checkout with generated.patch applied):

1. Structural assertions that the candidate source contains the security fix
   (net/netip import, netip.ParseAddr + AsSlice in useProxy, and the ip != nil
   guard at the top of domainMatch.match).
2. A faithful Python model of the target's useProxy/init/matcher semantics,
   parameterised by what the source actually contains, exercised with
   regression cases. The model mirrors the Go control flow; it is NOT the Go
   runtime and does not substitute for compiling/running the package.

Exit code 0 = all assertions and model cases pass.
"""
from __future__ import annotations

import argparse
import ipaddress
import sys
from pathlib import Path

REL = "src/vendor/golang.org/x/net/http/httpproxy/proxy.go"


def read_source(root: Path) -> str:
    path = root / REL
    if not path.is_file():
        print(f"FAIL: {path} not found", file=sys.stderr)
        sys.exit(2)
    return path.read_text(encoding="utf-8")


def structural_checks(src: str) -> list[str]:
    findings = []
    if '"net/netip"' not in src:
        findings.append('missing import "net/netip"')
    if "netip.ParseAddr(host)" not in src:
        findings.append("useProxy does not call netip.ParseAddr(host)")
    if "net.IP(nip.AsSlice())" not in src:
        findings.append("useProxy does not convert with net.IP(nip.AsSlice())")
    marker = "func (m domainMatch) match(host, port string, ip net.IP) bool {\n\tif ip != nil {\n\t\treturn false\n\t}"
    if marker not in src:
        findings.append("domainMatch.match has no leading `if ip != nil { return false }` guard")
    if "net.ParseIP(host)" in src:
        findings.append("useProxy still contains the old net.ParseIP(host)")
    return findings


# --------------------------------------------------------------------------
# Model of golang.org/x/net/http/httpproxy, parameterised by the source.
# --------------------------------------------------------------------------
class Model:
    def __init__(self, use_netip: bool, domain_ip_guard: bool):
        self.use_netip = use_netip
        self.domain_ip_guard = domain_ip_guard

    # net.ParseIP rejects zone identifiers; netip.ParseAddr accepts and strips them.
    def parse_host(self, host: str):
        try:
            if self.use_netip:
                if "%" in host:
                    base, zone = host.split("%", 1)
                    if zone == "":
                        return None
                    return ipaddress.IPv6Address(base)  # zone stripped by AsSlice
                return ipaddress.ip_address(host)
            # net.ParseIP: no zone support
            if "%" in host:
                return None
            return ipaddress.ip_address(host)
        except ValueError:
            return None

    def use_proxy(self, addr: str, no_proxy: str = "") -> bool:
        if addr == "":
            return True
        # net.SplitHostPort
        if addr.startswith("["):
            end = addr.find("]")
            if end < 0:
                return False
            host = addr[1:end]
            port = addr[end + 2 :] if addr[end + 1 : end + 2] == ":" else ""
        else:
            if ":" not in addr:
                return False
            host, port = addr.rsplit(":", 1)
        if host == "localhost":
            return False
        ip = self.parse_host(host)
        if ip is not None and ip.is_loopback:
            return False

        ip_matchers, domain_matchers = self.init_matchers(no_proxy)
        if ip is not None:
            for kind, value, mport in ip_matchers:
                if kind == "all":
                    return False
                if kind == "cidr" and ip in value:
                    return False
                if kind == "ip" and ip == value and (mport == "" or mport == port):
                    return False
        for mhost, mport, match_host in domain_matchers:
            if self.domain_match(host, port, ip, mhost, mport, match_host):
                return False
        return True

    def domain_match(self, host, port, ip, mhost, mport, match_host) -> bool:
        if self.domain_ip_guard and ip is not None:
            return False
        if host.endswith(mhost) or (match_host and host == mhost[1:]):
            return mport == "" or mport == port
        return False

    def init_matchers(self, no_proxy: str):
        ip_matchers = []
        domain_matchers = []
        for raw in no_proxy.split(","):
            p = raw.strip().lower()
            if not p:
                continue
            if p == "*":
                return [("all", None, "")], [("*", "", True)]
            try:
                if "/" in p:
                    ip_matchers.append(("cidr", ipaddress.ip_network(p, strict=False), ""))
                    continue
            except ValueError:
                pass
            phost, pport = p, ""
            if p.startswith("["):
                end = p.find("]")
                if end > 0:
                    phost = p[1:end]
                    pport = p[end + 2 :] if p[end + 1 : end + 2] == ":" else ""
            elif ":" in p:
                maybe_host, maybe_port = p.rsplit(":", 1)
                try:
                    ipaddress.ip_address(maybe_port)
                except ValueError:
                    if maybe_port.isdigit():
                        phost, pport = maybe_host, maybe_port
            try:
                pip = ipaddress.ip_address(phost)
                ip_matchers.append(("ip", pip, pport))
                continue
            except ValueError:
                pass
            if not phost:
                continue
            if phost.startswith("*."):
                phost = phost[1:]
            match_host = phost[0] != "."
            if match_host:
                phost = "." + phost
            domain_matchers.append((phost, pport, match_host))
        return ip_matchers, domain_matchers


def main() -> int:
    ap = argparse.ArgumentParser()
    ap.add_argument("--root", default=".")
    ap.add_argument(
        "--expect",
        choices=["candidate", "baseline"],
        default="candidate",
        help="candidate expects the fix; baseline expects the vulnerable behavior",
    )
    args = ap.parse_args()
    root = Path(args.root).resolve()
    src = read_source(root)

    findings = structural_checks(src)
    if args.expect == "candidate" and findings:
        for f in findings:
            print("FAIL structural:", f, file=sys.stderr)
        return 1
    if args.expect == "baseline" and not findings:
        print("FAIL: baseline unexpectedly already contains the complete fix", file=sys.stderr)
        return 1

    use_netip = "netip.ParseAddr(host)" in src
    domain_guard = "func (m domainMatch) match(host, port string, ip net.IP) bool {\n\tif ip != nil {\n\t\treturn false\n\t}" in src
    print(f"detected: use_netip={use_netip} domain_ip_guard={domain_guard}")
    m = Model(use_netip, domain_ip_guard)

    failures = []

    def check(name, got, want):
        ok = got == want
        print(f"[{'PASS' if ok else 'FAIL'}] {name}: got={got} want={want}")
        if not ok:
            failures.append(name)

    # 1. Zone-qualified loopback literal with NO_PROXY=::1 (the CVE path).
    #    Vulnerable: net.ParseIP returns nil -> loopback missed, ipMatch skipped -> proxied.
    #    Fixed: netip parses ::1 and strips %eth0 -> loopback -> direct.
    check(
        "zoned loopback ::1%eth0 vs NO_PROXY=::1",
        m.use_proxy("[::1%eth0]:80", "::1"),
        False if args.expect == "candidate" else True,
    )

    # 2. Zone-qualified IPv6 literal with a matching CIDR entry.
    check(
        "zoned literal fe80::1%eth0 vs NO_PROXY=fe80::/10",
        m.use_proxy("[fe80::1%eth0]:80", "fe80::/10"),
        False if args.expect == "candidate" else True,
    )

    # 3. Plain IPv4 loopback remains direct (regression guard, both versions).
    check("plain loopback 127.0.0.1", m.use_proxy("127.0.0.1:80", ""), False)

    # 4. Hostname domain matching unchanged (positive path, both versions).
    check("hostname example.com matches .example.com", m.use_proxy("example.com:80", "example.com"), False)
    check("hostname other.org not matched", m.use_proxy("other.org:80", "example.com"), True)

    # 5. Plain IP literal must not be matched by a domain suffix (fix guard).
    #    Vulnerable: domain matcher matches "127.0.0.1" by suffix ".0.0.1" -> direct.
    #    Fixed: domainMatch returns false for ip != nil -> no match -> proxied.
    check(
        "plain IP 127.0.0.1 vs domain NO_PROXY=0.0.1",
        m.use_proxy("127.0.0.1:80", "0.0.1"),
        True if args.expect == "candidate" else False,
    )

    # 6. Zone must not let a domain matcher fire on an IP literal.
    check(
        "zoned literal vs domain-like NO_PROXY=1%eth0",
        m.use_proxy("[::1%eth0]:80", "1%eth0"),
        True,
    )

    if failures:
        print(f"MODEL FAILURES: {failures}", file=sys.stderr)
        return 1
    print(f"all model cases passed ({args.expect})")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())

