        ip_matchers = []
        domain_matchers = []
        for raw in no_proxy.split(","):
            p = raw.strip().lower()
            if not p:
                continue
            if p == "*":
                return [("all", None, "")], [("*", "", True)]
            try:
                if "/" in p:
                    ip_matchers.append(("cidr", ipaddress.ip_network(p, strict=False), ""))
                    continue
            except ValueError:
                pass
            phost, pport = p, ""
            if p.startswith("["):
                end = p.find("]")
                if end > 0:
                    phost = p[1:end]
                    pport = p[end + 2 :] if p[end + 1 : end + 2] == ":" else ""
            elif ":" in p:
                maybe_host, maybe_port = p.rsplit(":", 1)
                try:
                    ipaddress.ip_address(maybe_port)
                except ValueError:
                    if maybe_port.isdigit():
                        phost, pport = maybe_host, maybe_port
            try:
                pip = ipaddress.ip_address(phost)
                ip_matchers.append(("ip", pip, pport))
                continue
            except ValueError:
                pass
            if not phost:
                continue
            if phost.startswith("*."):
                phost = phost[1:]
            match_host = phost[0] != "."
            if match_host:
                phost = "." + phost
            domain_matchers.append((phost, pport, match_host))
        return ip_matchers, domain_matchers


def main() -> int:
    ap = argparse.ArgumentParser()
    ap.add_argument("--root", default=".")
    ap.add_argument(
        "--expect",
        choices=["candidate", "baseline"],
        default="candidate",
        help="candidate expects the fix; baseline expects the vulnerable behavior",
    )
    args = ap.parse_args()
    root = Path(args.root).resolve()
    src = read_source(root)

    findings = structural_checks(src)
    if args.expect == "candidate" and findings:
        for f in findings:
            print("FAIL structural:", f, file=sys.stderr)
        return 1
    if args.expect == "baseline" and not findings:
        print("FAIL: baseline unexpectedly already contains the complete fix", file=sys.stderr)
        return 1

    use_netip = "netip.ParseAddr(host)" in src
    domain_guard = "func (m domainMatch) match(host, port string, ip net.IP) bool {\n\tif ip != nil {\n\t\treturn false\n\t}" in src
    print(f"detected: use_netip={use_netip} domain_ip_guard={domain_guard}")
    m = Model(use_netip, domain_guard)

    failures = []
    candidate_run = args.expect == "candidate"

    def check(name, got, candidate_want, baseline_want):
        want = candidate_want if candidate_run else baseline_want
        ok = got == want
        print(f"[{'PASS' if ok else 'FAIL'}] {name}: got={got} want={want}")
        if not ok:
            failures.append(name)

    # 1. Zone-qualified loopback literal with NO_PROXY=::1 (the CVE path).
    #    Vulnerable: net.ParseIP returns nil -> loopback missed, ipMatch skipped -> proxied.
    #    Fixed: netip parses ::1 and strips %eth0 -> loopback -> direct.
    check(
        "zoned loopback ::1%eth0 vs NO_PROXY=::1",
        m.use_proxy("[::1%eth0]:80", "::1"),
        candidate_want=False,
        baseline_want=True,
    )

    # 2. Zone-qualified IPv6 literal with a matching CIDR entry.
    check(
        "zoned literal fe80::1%eth0 vs NO_PROXY=fe80::/10",
        m.use_proxy("[fe80::1%eth0]:80", "fe80::/10"),
        candidate_want=False,
        baseline_want=True,
    )

    # 3. Plain IPv4 loopback remains direct (regression guard, both versions).
    check("plain loopback 127.0.0.1", m.use_proxy("127.0.0.1:80", ""), False, False)

    # 4. Hostname domain matching unchanged (positive path, both versions).
    check("hostname example.com matches .example.com", m.use_proxy("example.com:80", "example.com"), False, False)
    check("hostname other.org not matched", m.use_proxy("other.org:80", "example.com"), True, True)

    # 5. Plain IP literal must not be matched by a domain suffix (fix guard).
    #    Vulnerable: domain matcher matches "10.0.0.1" by suffix ".0.0.1" -> direct.
    #    Fixed: domainMatch returns false for ip != nil -> no match -> proxied.
    #    NB: net.ParseIP("0.0.1") is nil in Go, so the entry is a domain matcher.
    check(
        "plain IP 10.0.0.1 vs domain NO_PROXY=0.0.1",
        m.use_proxy("10.0.0.1:80", "0.0.1"),
        candidate_want=True,
        baseline_want=False,
    )

    # 6. A zone suffix must not let a domain matcher fire on an IP literal.
    check(
        "zoned literal fe80::1%a.b vs domain NO_PROXY=b",
        m.use_proxy("[fe80::1%a.b]:80", "b"),
        candidate_want=True,
        baseline_want=False,
    )

    if failures:
        print(f"MODEL FAILURES: {failures}", file=sys.stderr)
        return 1
    print(f"all model cases passed ({args.expect})")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())

